RegisterBankInfo::PartialMapping AIE2PSGenRegisterBankInfo::PartMappings[]{
    // StartIdx, Length, RegBank
    // 0: GPR 32-bit value
    {0, 32, AIE2PS::GPRRegBank},
    // 1: PTR 20-bit value
    {0, 20, AIE2PS::PTRRegBank},
    // 2: MOD 20-bit value
    {0, 20, AIE2PS::MODRegBank},
    // 3(PMI_CB)
    {},
    // 4: GPR 64-bit value
    {0, 64, AIE2PS::GPRRegBank},
    // 5(undef),6(undef)
    {},
    {},
    // 7: VREG 256-bit value
    {0, 256, AIE2PS::VRegBank},
    // 8: VREG 512-bit value
    {0, 512, AIE2PS::VRegBank},
    // 9: VREG 1024-bit value
    {0, 1024, AIE2PS::VRegBank},
    // 10: AccREG 256-bit value
    {},
    // 11: AccREG 512-bit value
    {0, 512, AIE2PS::AccRegBank},
    // 12: AccREG 1024-bit value
    {0, 1024, AIE2PS::AccRegBank},
    // 13: VREG 128-bit value
    {0, 128, AIE2PS::VRegBank},
    // 14: AccREG 2048-bit value
    {0, 2048, AIE2PS::AccRegBank},
    // 15: FifoREG 512-bit value
    {0, 512, AIE2PS::FifoRegBank},
    // 16: FifoREG 1024-bit value
    {0, 1024, AIE2PS::FifoRegBank},
};

// ValueMappings.
RegisterBankInfo::ValueMapping AIE2PSGenRegisterBankInfo::ValMappings[]{
    /* BreakDown, NumBreakDowns */
    // 0: invalid
    {nullptr, 0},
    // 3-operands instructions
    // 1: GPR 32-bit value. <-- This must match First3OpsIdx.
    {&PartMappings[PMI_GPR - PMI_Min], 1},
    {&PartMappings[PMI_GPR - PMI_Min], 1},
    {&PartMappings[PMI_GPR - PMI_Min], 1},
    // 4: PTR 20-bit value.
    {&PartMappings[PMI_PTR - PMI_Min], 1},
    {&PartMappings[PMI_PTR - PMI_Min], 1},
    {&PartMappings[PMI_PTR - PMI_Min], 1},
    // 7: MOD 20-bit value. <-- This must match Last3OpsIdx
    {&PartMappings[PMI_MOD - PMI_Min], 1},
    {&PartMappings[PMI_MOD - PMI_Min], 1},
    {&PartMappings[PMI_MOD - PMI_Min], 1},
    // 10: AIE1's CB:
    {},
    {},
    {},
    // 13: GPR 64-bit value.
    {&PartMappings[PMI_GPR64 - PMI_Min], 1},
    {&PartMappings[PMI_GPR64 - PMI_Min], 1},
    {&PartMappings[PMI_GPR64 - PMI_Min], 1},
    // 16:
    {&PartMappings[PMI_VREG256 - PMI_Min], 1},
    {&PartMappings[PMI_VREG256 - PMI_Min], 1},
    {&PartMappings[PMI_VREG256 - PMI_Min], 1},
    // 19:
    {&PartMappings[PMI_VREG512 - PMI_Min], 1},
    {&PartMappings[PMI_VREG512 - PMI_Min], 1},
    {&PartMappings[PMI_VREG512 - PMI_Min], 1},
    // 22:
    {&PartMappings[PMI_VREG1024 - PMI_Min], 1},
    {&PartMappings[PMI_VREG1024 - PMI_Min], 1},
    {&PartMappings[PMI_VREG1024 - PMI_Min], 1},
    // 25: AIE2's ACC256:
    {},
    // 26:
    {&PartMappings[PMI_ACC512 - PMI_Min], 1},
    // 27:
    {&PartMappings[PMI_ACC1024 - PMI_Min], 1},
    // 28:
    {&PartMappings[PMI_VREG128 - PMI_Min], 1},
    // 29:
    {&PartMappings[PMI_ACC2048 - PMI_Min], 1},
    // 30:
    {&PartMappings[PMI_FIFO512 - PMI_Min], 1},
    // 31
    {&PartMappings[PMI_FIFO1024 - PMI_Min], 1}};

const RegisterBankInfo::ValueMapping *
AIE2PSGenRegisterBankInfo::getValueMapping(PartialMappingIdx RBIdx,
                                           unsigned Size) const {
  assert(RBIdx != PartialMappingIdx::PMI_None && "No mapping needed for that");
  unsigned BaseIdxOffset = getRegBankBaseIdxOffset(RBIdx, Size);
  if (BaseIdxOffset == -1u)
    return &ValMappings[InvalidIdx];

  unsigned ValMappingIdx;
  PartialMappingIdx PMIdx;
  ValueMappingIdx VMIdx = ValueMappingIdx::First3OpsIdx;
  ValueMappingIdx DistRegBanks = ValueMappingIdx::DistanceBetweenRegBanks;
  switch (RBIdx) {
  case PMI_GPR:
  case PMI_PTR:
  case PMI_MOD:
  case PMI_GPR64:
    PMIdx = PartialMappingIdx::PMI_Min;
    break;
  case PMI_VREG128:
    PMIdx = PartialMappingIdx::PMI_VREG128;
    VMIdx = ValueMappingIdx::S128_Idx;
    break;
  case PMI_VREG256:
  case PMI_VREG512:
  case PMI_VREG1024:
    PMIdx = PartialMappingIdx::PMI_VREGMin;
    VMIdx = ValueMappingIdx::FirstVecOpsIdx;
    break;
  case PMI_ACC512:
  case PMI_ACC1024:
  case PMI_ACC2048:
    PMIdx = PartialMappingIdx::PMI_ACC512;
    DistRegBanks = ValueMappingIdx::DistanceBetweenAccRegBanks;
    VMIdx = ValueMappingIdx::FirstAccOpsIdx;
    break;
  case PMI_FIFO512:
  case PMI_FIFO1024:
    PMIdx = PartialMappingIdx::PMI_FIFO512;
    VMIdx = ValueMappingIdx::FirstFifoOpsIdx;
    DistRegBanks = ValueMappingIdx::DistanceBetweenFifoRegBanks;
    break;
  default:
    llvm_unreachable("Unsupported PartialMappingIdx.");
  }
  ValMappingIdx = VMIdx + (RBIdx - PMIdx + BaseIdxOffset) * DistRegBanks;
  assert(ValMappingIdx >= First3OpsIdx && ValMappingIdx <= LastOpsIdx &&
         "Mapping out of bound");
  return &ValMappings[ValMappingIdx];
}

AIEBaseRegisterBankInfo::PartialMappingIdx
AIE2PSGenRegisterBankInfo::getPartialMappingIdx(const LLT &Ty) const {
  if (Ty.isPointer() || Ty.isScalar() ||
      (Ty.isVector() && Ty.getSizeInBits() <= 256))
    return AIEBaseRegisterBankInfo::getPartialMappingIdx(Ty);
  if (Ty.isVector()) {
    switch (Ty.getSizeInBits()) {
    case 512:
      return PMI_VREG512;
    case 1024:
      return PMI_VREG1024;
    case 2048:
      return PMI_ACC2048;
    default:
      llvm_unreachable("Unsupported register size for vector type.");
    }
  }
  llvm_unreachable("Unsupported register type for partial mapping.");
}

AIEBaseRegisterBankInfo::PartialMappingIdx
AIE2PSGenRegisterBankInfo::getAccPartialMappingIdx(const LLT &Ty) const {
  // in aie2ps 2048-bit sized type is an accumulator.
  if (Ty.getSizeInBits() == 2048)
    return PMI_ACC2048;
  return AIEBaseRegisterBankInfo::getAccPartialMappingIdx(Ty);
}

AIEBaseRegisterBankInfo::PartialMappingIdx
AIE2PSGenRegisterBankInfo::getFifoPartialMappingIdx(const LLT &Ty) const {
  if (Ty.getSizeInBits() == 512)
    return PMI_FIFO512;
  if (Ty.getSizeInBits() == 1024)
    return PMI_FIFO1024;
  llvm_unreachable("Unsupported fifo register size.");
}

AIEBaseRegisterBankInfo::PartialMappingIdx
AIE2PSGenRegisterBankInfo::getPartialMappingIdxFromBankAndType(
    std::optional<const RegisterBank *> RegBank, const LLT &Ty) const {
  assert(RegBank && "Not a valid vector type!");
  if (&AIE2PS::AccRegBank == *RegBank) {
    return getAccPartialMappingIdx(Ty);
  } else if (&AIE2PS::FifoRegBank == *RegBank) {
    return getFifoPartialMappingIdx(Ty);
  } else {
    return getVecPartialMappingIdx(Ty);
  }
}

AIE2PSRegisterBankInfo::AIE2PSRegisterBankInfo(const TargetRegisterInfo &TRI)
    : AIE2PSGenRegisterBankInfo() {

  static llvm::once_flag InitializeRegisterBankFlag;

  static auto InitializeRegisterBankOnce = [&]() {
    // We have only one set of register banks, whatever the subtarget
    // is. Therefore, the initialization of the RegBanks table should be
    // done only once. Indeed the table of all register banks
    // (AIE2PS::RegBanks) is unique in the compiler. At some point, it
    // will get tablegen'ed and the whole constructor becomes empty.
    assert(&getRegBank(AIE2PS::GPRRegBankID) == &AIE2PS::GPRRegBank &&
           &getRegBank(AIE2PS::PTRRegBankID) == &AIE2PS::PTRRegBank &&
           "The order in RegBanks is messed up");
    assert(verify(TRI) && "Invalid register bank information");
  };

  llvm::call_once(InitializeRegisterBankFlag, InitializeRegisterBankOnce);
}

static bool isAccReg(const Register Reg) {
  if (Reg.isPhysical() && (AIE2PS::ACC512RegClass.contains(Reg) ||
                           AIE2PS::ACC1024RegClass.contains(Reg) ||
                           AIE2PS::ACC2048RegClass.contains(Reg)))
    return true;
  return false;
}

static bool isRegisterInOperandList(const MachineInstr &MI, const Register Reg,
                                    const std::set<unsigned> Operands) {
  for (auto Idx : Operands) {
    if (Reg == MI.getOperand(Idx).getReg())
      return true;
  }
  return false;
}

static bool checkFifoDstSrc(const MachineInstr &MI,
                            const Register &FifoRegCandidate,
                            unsigned DstOpIndex, unsigned SrcOpIndex) {
  Register FifoDstReg = MI.getOperand(DstOpIndex).getReg();
  Register FifoSrcReg = MI.getOperand(SrcOpIndex).getReg();
  return ((FifoRegCandidate == FifoDstReg) || (FifoRegCandidate == FifoSrcReg));
}

// Check if FifoRegCandidate is one of the fifo operands of the intrinsic
static bool isUsedAsFifoRegInIntrinsic(const MachineRegisterInfo &MRI,
                                       const MachineInstr &MI,
                                       const Register FifoRegCandidate) {
  switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
  // TODO: To be extented with more FIFO using intrinsics
  case Intrinsic::aie2ps_fifo_ld_fill: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 5);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_pop_512_unaligned:
  case Intrinsic::aie2ps_fifo_ld_pop_1d_unaligned: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 2, 6);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_pop_BFP640: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 8);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_pop_BFP768:
  case Intrinsic::aie2ps_fifo_ld_pop_1d_BFP768: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 13);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_pop_1d_BFP640:
  case Intrinsic::aie2ps_fifo_ld_pop_2d_BFP640: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 9);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_pop_2d_BFP768: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 14);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_pop_2d_unaligned: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 2, 7);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_pop_3d_unaligned: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 2, 8);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_pop_3d_BFP640: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 10);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_pop_3d_BFP768: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 15);
    break;
  }
  case Intrinsic::aie2ps_fifo_st_flush:
  case Intrinsic::aie2ps_fifo_st_flush_conv:
  case Intrinsic::aie2ps_fifo_st_flush_1d:
  case Intrinsic::aie2ps_fifo_st_flush_1d_conv:
  case Intrinsic::aie2ps_fifo_st_push_BFP384:
  case Intrinsic::aie2ps_fifo_st_push_BFP768:
  case Intrinsic::aie2ps_fifo_st_push_BFP640: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 5);
    break;
  }
  case Intrinsic::aie2ps_fifo_st_push_512:
  case Intrinsic::aie2ps_fifo_st_flush_2d:
  case Intrinsic::aie2ps_fifo_st_flush_2d_conv: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 6);
    break;
  }
  case Intrinsic::aie2ps_fifo_st_flush_3d:
  case Intrinsic::aie2ps_fifo_st_flush_3d_conv: {
    return checkFifoDstSrc(MI, FifoRegCandidate, 1, 7);
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_fillx: {
    Register FifoExtraDstReg = MI.getOperand(3).getReg();
    Register FifoExtraSrcReg = MI.getOperand(8).getReg();
    return (checkFifoDstSrc(MI, FifoRegCandidate, 1, 6) ||
            (FifoRegCandidate == FifoExtraDstReg) ||
            (FifoRegCandidate == FifoExtraSrcReg));
    break;
  }
  case Intrinsic::aie2ps_fifo_ld_popx: {
    Register FifoExtraDstReg = MI.getOperand(4).getReg();
    Register FifoExtraSrcReg = MI.getOperand(9).getReg();
    return (checkFifoDstSrc(MI, FifoRegCandidate, 2, 7) ||
            (FifoRegCandidate == FifoExtraDstReg) ||
            (FifoRegCandidate == FifoExtraSrcReg));
    break;
  }
  default:
    return false;
  }
  return false;
}

/// \returns true if the specified intrinsic has an accumulator
/// vector as one of its operands.
static bool isUsedAsAccRegInIntrinsic(const MachineRegisterInfo &MRI,
                                      const MachineInstr &MI,
                                      const Register AccReg) {
  std::set<unsigned> AccumulatorOps;
  assert(MI.getOpcode() == TargetOpcode::G_INTRINSIC ||
         MI.getOpcode() == TargetOpcode::G_INTRINSIC_W_SIDE_EFFECTS);

  switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
  // Category 1: Operand 0 only (Output Accumulator)
  // UPS operations
  case Intrinsic::aie2ps_acc32_v16_I256_ups:
  case Intrinsic::aie2ps_acc32_v32_I256_ups:
  case Intrinsic::aie2ps_acc32_v32_I512_ups:
  case Intrinsic::aie2ps_acc64_v16_I256_ups:
  case Intrinsic::aie2ps_acc64_v16_I512_ups:
  case Intrinsic::aie2ps_acc64_v8_I256_ups:
  case Intrinsic::aie2ps_acc32_v64_I512_ups:
  case Intrinsic::aie2ps_acc64_v32_I512_ups:
  // Float16/BFloat16 to AccFloat conversions
  case Intrinsic::aie2ps_v16float16_to_v16accfloat:
  case Intrinsic::aie2ps_v32float16_to_v32accfloat:
  case Intrinsic::aie2ps_v16bf16_to_v16accfloat:
  case Intrinsic::aie2ps_v32bf16_to_v32accfloat:
  // CLR operations
  case Intrinsic::aie2ps_clr_ACC1024l_conf:
  case Intrinsic::aie2ps_clr_ACC2048_conf:
  // Stream read operations
  case Intrinsic::aie2ps_scd_read_acc32:
  case Intrinsic::aie2ps_scd_expand_lo:
  case Intrinsic::aie2ps_scd_expand_hi:
  case Intrinsic::aie2ps_scd_expand_ACC1024:
  case Intrinsic::aie2ps_scd_ACC2048:
  case Intrinsic::aie2ps_scd_expand_ACC2048:
  case Intrinsic::aie2ps_scd_expand_ACC1024_incr:
  case Intrinsic::aie2ps_scd_expand_ACC2048_incr:
  case Intrinsic::aie2ps_BFP640_BFP2560_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_BFP640_BFP2560_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_BFP768_BFP1536_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_BFP768_BFP1536_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_I1024_I1024_ACC2048_mul_conf:
  case Intrinsic::aie2ps_I1024_I1024_ACC2048_negmul_conf:
  case Intrinsic::aie2ps_I1024_I512_ACC2048_mul_conf:
  case Intrinsic::aie2ps_I1024_I512_ACC2048_negmul_conf:
  case Intrinsic::aie2ps_I1024_short_ACC2048_mul_conf:
  case Intrinsic::aie2ps_I1024_short_ACC2048_negmul_conf:
  case Intrinsic::aie2ps_I512_char_ACC2048_mul_conf:
  case Intrinsic::aie2ps_I512_char_ACC2048_negmul_conf:
  case Intrinsic::aie2ps_I512_I1024_ACC2048_mul_conf:
  case Intrinsic::aie2ps_I512_I1024_ACC2048_negmul_conf:
  case Intrinsic::aie2ps_I512_I512_ACC2048_mul_conf:
  case Intrinsic::aie2ps_I512_I512_ACC2048_negmul_conf:
  case Intrinsic::aie2ps_I512_short_ACC2048_mul_conf:
  case Intrinsic::aie2ps_I512_short_ACC2048_negmul_conf:
  case Intrinsic::aie2ps_I512_I512_ACC1024_mul_conf:
  case Intrinsic::aie2ps_I512_I512_ACC1024_negmul_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_I1024_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_I1024_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_I1024_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_I1024_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I1024_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I1024_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I512_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I512_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I1024_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I1024_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I512_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I512_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_I1024_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_I1024_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_I1024_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_I1024_ACC2048_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I1024_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I1024_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I512_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I512_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I1024_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I1024_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I512_ACC1024_bf_mul_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I512_ACC1024_bf_negmul_conf:
  case Intrinsic::aie2ps_fp8_I512_fp8_I512_ACC2048_bf_mul_conf:
  case Intrinsic::aie2ps_fp8_I512_fp8_I512_ACC2048_bf_negmul_conf: {
    AccumulatorOps = {0};
    break;
  }

  // Category 2: Operand 1 only (Input Accumulator)
  // Stream write operations
  case Intrinsic::aie2ps_mcd_write_acc32: {
    AccumulatorOps = {1};
    break;
  }

  // Category 3: Operand 2 only (Input Accumulator)
  // SRS operations
  case Intrinsic::aie2ps_I256_v16_acc32_srs:
  case Intrinsic::aie2ps_I256_v16_acc64_srs:
  case Intrinsic::aie2ps_I256_v32_acc32_srs:
  case Intrinsic::aie2ps_I256_v8_acc64_srs:
  case Intrinsic::aie2ps_I512_v16_acc64_srs:
  case Intrinsic::aie2ps_I512_v32_acc32_srs:
  case Intrinsic::aie2ps_I512_v32_acc64_srs:
  case Intrinsic::aie2ps_I512_v64_acc32_srs:
  // AccFloat to other type conversions
  case Intrinsic::aie2ps_v16accfloat_to_v16bf16:
  case Intrinsic::aie2ps_v32accfloat_to_v32bf16:
  case Intrinsic::aie2ps_v16accfloat_to_v16float16:
  case Intrinsic::aie2ps_v32accfloat_to_v32float16:
  case Intrinsic::aie2ps_v32accfloat_to_v32float8:
  case Intrinsic::aie2ps_v32accfloat_to_v32bfloat8:
  case Intrinsic::aie2ps_v64accfloat_to_v64mx4:
  case Intrinsic::aie2ps_v64accfloat_to_v64mx6:
  case Intrinsic::aie2ps_v64accfloat_to_v64mx9:
  // NLF with AccFloat
  case Intrinsic::aie2ps_exp2:
  case Intrinsic::aie2ps_tanh: {
    AccumulatorOps = {2};
    break;
  }

  // Category 4: Operands 0 and 2 (Output + Input Accumulator)
  case Intrinsic::aie2ps_exp2_bf20:
  case Intrinsic::aie2ps_ACC2048_neg_conf:
  case Intrinsic::aie2ps_ACC2048_accfloat_neg_conf:
  case Intrinsic::aie2ps_ACC1024_neg_conf:
  case Intrinsic::aie2ps_ACC1024_accfloat_neg_conf: {
    AccumulatorOps = {0, 2};
    break;
  }

  // Category 5: Operands 0, 2 and 3 (Output + Input Accumulator)
  case Intrinsic::aie2ps_ACC2048_sub_conf:
  case Intrinsic::aie2ps_ACC2048_accfloat_sub_conf:
  case Intrinsic::aie2ps_ACC2048_accfloat_add_conf:
  case Intrinsic::aie2ps_ACC2048_add_conf:
  case Intrinsic::aie2ps_ACC1024_sub_conf:
  case Intrinsic::aie2ps_ACC1024_accfloat_sub_conf:
  case Intrinsic::aie2ps_ACC1024_accfloat_add_conf:
  case Intrinsic::aie2ps_ACC1024_add_conf: {
    AccumulatorOps = {0, 2, 3};
    break;
  }
  // Category 6: Operands 0 and 4 (Output + Input Accumulator)
  // Integer MAC/MUL operations (ACC2048)
  case Intrinsic::aie2ps_I1024_I1024_ACC2048_mac_conf:
  case Intrinsic::aie2ps_I1024_I1024_ACC2048_msc_conf:
  case Intrinsic::aie2ps_I1024_I512_ACC2048_mac_conf:
  case Intrinsic::aie2ps_I1024_I512_ACC2048_msc_conf:
  case Intrinsic::aie2ps_I1024_short_ACC2048_mac_conf:
  case Intrinsic::aie2ps_I1024_short_ACC2048_msc_conf:
  case Intrinsic::aie2ps_I512_char_ACC2048_mac_conf:
  case Intrinsic::aie2ps_I512_char_ACC2048_msc_conf:
  case Intrinsic::aie2ps_I512_I1024_ACC2048_mac_conf:
  case Intrinsic::aie2ps_I512_I1024_ACC2048_msc_conf:
  case Intrinsic::aie2ps_I512_I512_ACC2048_mac_conf:
  case Intrinsic::aie2ps_I512_I512_ACC2048_msc_conf:
  case Intrinsic::aie2ps_I512_short_ACC2048_mac_conf:
  case Intrinsic::aie2ps_I512_short_ACC2048_msc_conf:
  // Integer MAC/MUL operations (ACC1024)
  case Intrinsic::aie2ps_I512_I512_ACC1024_mac_conf:
  case Intrinsic::aie2ps_I512_I512_ACC1024_msc_conf:
  // BFloat16 MAC/MUL operations (ACC2048)
  case Intrinsic::aie2ps_bf16_I1024_bf16_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_ACC2048_bf_msc_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_I1024_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_I1024_ACC2048_bf_msc_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_ACC2048_bf_msc_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_I1024_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_I1024_ACC2048_bf_msc_conf:
  // BFloat16 MAC/MUL operations (ACC1024)
  case Intrinsic::aie2ps_bf16_I512_bf16_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I1024_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I1024_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I512_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I512_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I1024_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I1024_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I512_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I512_ACC1024_bf_msc_conf:
  // Float16 MAC/MUL operations (ACC2048)
  case Intrinsic::aie2ps_fp16_I1024_bf16_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_ACC2048_bf_msc_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_I1024_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_I1024_ACC2048_bf_msc_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_ACC2048_bf_msc_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_I1024_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_I1024_ACC2048_bf_msc_conf:
  // Float16 MAC/MUL operations (ACC1024)
  case Intrinsic::aie2ps_fp16_I512_bf16_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I1024_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I1024_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I512_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I512_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I1024_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I1024_ACC1024_bf_msc_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I512_ACC1024_bf_mac_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I512_ACC1024_bf_msc_conf:
  // Float8 MAC/MUL operations (ACC2048)
  case Intrinsic::aie2ps_fp8_I512_fp8_I512_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_fp8_I512_fp8_I512_ACC2048_bf_msc_conf: {
    AccumulatorOps = {0, 4};
    break;
  }

  // Category 7: Operands 0, 4, and 5 (ADDMAC operations)
  // Integer ADDMAC operations (ACC2048)
  case Intrinsic::aie2ps_I1024_I1024_ACC2048_addmac_conf:
  case Intrinsic::aie2ps_I1024_I1024_ACC2048_addmsc_conf:
  case Intrinsic::aie2ps_I1024_I512_ACC2048_addmac_conf:
  case Intrinsic::aie2ps_I1024_I512_ACC2048_addmsc_conf:
  case Intrinsic::aie2ps_I1024_short_ACC2048_addmac_conf:
  case Intrinsic::aie2ps_I1024_short_ACC2048_addmsc_conf:
  case Intrinsic::aie2ps_I512_char_ACC2048_addmac_conf:
  case Intrinsic::aie2ps_I512_char_ACC2048_addmsc_conf:
  case Intrinsic::aie2ps_I512_I1024_ACC2048_addmac_conf:
  case Intrinsic::aie2ps_I512_I1024_ACC2048_addmsc_conf:
  case Intrinsic::aie2ps_I512_I512_ACC2048_addmac_conf:
  case Intrinsic::aie2ps_I512_I512_ACC2048_addmsc_conf:
  case Intrinsic::aie2ps_I512_short_ACC2048_addmac_conf:
  case Intrinsic::aie2ps_I512_short_ACC2048_addmsc_conf:
  // Integer ADDMAC operations (ACC1024)
  case Intrinsic::aie2ps_I512_I512_ACC1024_addmac_conf:
  case Intrinsic::aie2ps_I512_I512_ACC1024_addmsc_conf:
  // BFloat16 ADDMAC operations (ACC2048)
  case Intrinsic::aie2ps_bf16_I1024_bf16_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_ACC2048_bf_addmsc_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_I1024_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I1024_bf16_I1024_ACC2048_bf_addmsc_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_ACC2048_bf_addmsc_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_I1024_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I1024_fp16_I1024_ACC2048_bf_addmsc_conf:
  // BFloat16 ADDMAC operations (ACC1024)
  case Intrinsic::aie2ps_bf16_I512_bf16_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I1024_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I1024_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I512_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I512_bf16_I512_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I1024_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I1024_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I512_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_bf16_I512_fp16_I512_ACC1024_bf_addmsc_conf:
  // Float16 ADDMAC operations (ACC2048)
  case Intrinsic::aie2ps_fp16_I1024_bf16_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_ACC2048_bf_addmsc_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_I1024_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I1024_bf16_I1024_ACC2048_bf_addmsc_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_ACC2048_bf_addmsc_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_I1024_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I1024_fp16_I1024_ACC2048_bf_addmsc_conf:
  // Float16 ADDMAC operations (ACC1024)
  case Intrinsic::aie2ps_fp16_I512_bf16_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I1024_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I1024_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I512_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I512_bf16_I512_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I1024_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I1024_ACC1024_bf_addmsc_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I512_ACC1024_bf_addmac_conf:
  case Intrinsic::aie2ps_fp16_I512_fp16_I512_ACC1024_bf_addmsc_conf:
  // Float8 ADDMAC operations (ACC2048)
  case Intrinsic::aie2ps_fp8_I512_fp8_I512_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_fp8_I512_fp8_I512_ACC2048_bf_addmsc_conf: {
    AccumulatorOps = {0, 4, 5};
    break;
  }
  case Intrinsic::aie2ps_BFP640_BFP2560_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_BFP640_BFP2560_ACC2048_bf_msc_conf: {
    AccumulatorOps = {0, 17};
    break;
  }
  case Intrinsic::aie2ps_BFP640_BFP2560_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_BFP640_BFP2560_ACC2048_bf_addmsc_conf: {
    AccumulatorOps = {0, 17, 18};
    break;
  }
  case Intrinsic::aie2ps_BFP768_BFP1536_ACC2048_bf_mac_conf:
  case Intrinsic::aie2ps_BFP768_BFP1536_ACC2048_bf_msc_conf: {
    AccumulatorOps = {0, 26};
    break;
  }
  case Intrinsic::aie2ps_BFP768_BFP1536_ACC2048_bf_addmac_conf:
  case Intrinsic::aie2ps_BFP768_BFP1536_ACC2048_bf_addmsc_conf: {
    AccumulatorOps = {0, 26, 27};
    break;
  }

  default:
    break;
  }
  return isRegisterInOperandList(MI, AccReg, AccumulatorOps);
}

static bool isUsedAsAccRegInInstr(const MachineInstr &MI,
                                  const MachineRegisterInfo &MRI,
                                  const TargetRegisterInfo &TRI, Register Reg) {
  switch (MI.getOpcode()) {
  default:
    break;
  case TargetOpcode::G_INTRINSIC:
  case TargetOpcode::G_INTRINSIC_W_SIDE_EFFECTS:
    return isUsedAsAccRegInIntrinsic(MRI, MI, Reg);
  case TargetOpcode::COPY: {
    Register DstReg = MI.getOperand(0).getReg();
    if (isAccReg(DstReg))
      return true;
    break;
  }
  }
  return false;
}

// Check if the instruction has Reg as a fifo input.
// Similar to usesAccReg for Accumulators
static bool isUsedAsFifoRegInInstr(const MachineInstr &MI,
                                   const MachineRegisterInfo &MRI,
                                   const TargetRegisterInfo &TRI,
                                   Register Reg) {
  const MachineFunction &MF = *MI.getParent()->getParent();
  auto *RI = static_cast<const AIEBaseRegisterInfo *>(
      MF.getSubtarget().getRegisterInfo());
  switch (MI.getOpcode()) {
  default:
    break;
  case TargetOpcode::G_INTRINSIC:
  case TargetOpcode::G_INTRINSIC_W_SIDE_EFFECTS:
    return isUsedAsFifoRegInIntrinsic(MRI, MI, Reg);
  case TargetOpcode::COPY: {
    Register DstReg = MI.getOperand(0).getReg();
    if (RI->isFifoPhysReg(DstReg))
      return true;
    break;
  }
  }
  return false;
}

std::optional<const RegisterBank *>
AIE2PSRegisterBankInfo::getPreferredRegBankForVectorTy(
    const MachineRegisterInfo &MRI, const TargetRegisterInfo &TRI,
    Register Reg) const {
  LLT RegTy = MRI.getType(Reg);
  TypeSize RegSize = RegTy.getSizeInBits();
  if (RegSize <= 256 && RegSize > 64)
    return &getRegBank(AIE2PS::VRegBankID);
  if (RegSize > 2048)
    return std::nullopt; // AIE2PS doesn't have matrix registers

  if (registerBankLookAheadSearch(isUsedAsAccRegInInstr, MRI, TRI, Reg))
    return &getRegBank(AIE2PS::AccRegBankID);
  if (registerBankLookAheadSearch(isUsedAsFifoRegInInstr, MRI, TRI, Reg))
    return &getRegBank(AIE2PS::FifoRegBankID);
  if (RegSize == 2048)
    return &getRegBank(AIE2PS::AccRegBankID);
  if (RegSize > 64)
    return &getRegBank(AIE2PS::VRegBankID);
  return std::nullopt;
}

std::optional<const RegisterBank *>
AIE2PSRegisterBankInfo::getRegBankForVectorTy(const MachineRegisterInfo &MRI,
                                              const TargetRegisterInfo &TRI,
                                              const MachineInstr &MI,
                                              Register Reg) const {
  LLT RegTy = MRI.getType(Reg);
  TypeSize RegSize = RegTy.getSizeInBits();
  if (RegSize <= 256 && RegSize > 64)
    return &getRegBank(AIE2PS::VRegBankID);
  if (RegSize >= 2048)
    return &getRegBank(AIE2PS::AccRegBankID);
  if (isUsedAsAccRegInIntrinsic(MRI, MI, Reg))
    return &getRegBank(AIE2PS::AccRegBankID);
  if (isUsedAsFifoRegInIntrinsic(MRI, MI, Reg))
    return &getRegBank(AIE2PS::FifoRegBankID);
  if (RegSize > 64)
    return &getRegBank(AIE2PS::VRegBankID);
  return std::nullopt;
}

RegisterBankInfo::InstructionMappings
AIE2PSRegisterBankInfo::getInstrAlternativeMappings(
    const MachineInstr &MI) const {

  const MachineFunction &MF = *MI.getParent()->getParent();
  const TargetSubtargetInfo &STI = MF.getSubtarget();
  const TargetRegisterInfo &TRI = *STI.getRegisterInfo();
  const MachineRegisterInfo &MRI = MF.getRegInfo();
  switch (MI.getOpcode()) {
  case TargetOpcode::G_LOAD:
  case AIE2PS::G_AIE_OFFSET_LOAD:
  case AIE2PS::G_AIE_POSTINC_LOAD:
  case AIE2PS::G_AIE_POSTINC_2D_LOAD:
  case AIE2PS::G_AIE_POSTINC_3D_LOAD:
  case TargetOpcode::G_STORE:
  case AIE2PS::G_AIE_OFFSET_STORE:
  case AIE2PS::G_AIE_POSTINC_STORE:
  case AIE2PS::G_AIE_POSTINC_2D_STORE:
  case AIE2PS::G_AIE_POSTINC_3D_STORE:
  case TargetOpcode::G_UNMERGE_VALUES:
  case TargetOpcode::G_CONCAT_VECTORS:
  case TargetOpcode::G_IMPLICIT_DEF: {
    llvm_unreachable("Alternative mappings not implemented.");
    return {};
  }
  case TargetOpcode::G_BITCAST: {
    Register DstReg = MI.getOperand(0).getReg();
    unsigned Size = getSizeInBits(DstReg, MRI, TRI);
    // Only the accumulator is of 2048-bit size, with the possible mapping
    // restricted to accumulator register banks. For a 256-bit vector,
    // the only possible mapping is to a vector register bank.
    if (Size <= 256 || Size == 2048)
      break;

    // If the instruction has any implicit-defs or uses,
    // do not mess with it.
    if (MI.getNumOperands() != 2)
      break;

    InstructionMappings AltMappings;
    const InstructionMapping &VRegMapping = getInstructionMapping(
        /*ID*/ 1, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getVecPartialMappingIdx(MRI.getType(DstReg)),
                             Size),
             getValueMapping(getVecPartialMappingIdx(MRI.getType(DstReg)),
                             Size)}),
        /*NumOperands*/ 2);
    const InstructionMapping &AccRegMapping = getInstructionMapping(
        /*ID*/ 2, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getAccPartialMappingIdx(MRI.getType(DstReg)),
                             Size),
             getValueMapping(getAccPartialMappingIdx(MRI.getType(DstReg)),
                             Size)}),
        /*NumOperands*/ 2);
    const InstructionMapping &AccToVRegMapping = getInstructionMapping(
        /*ID*/ 3, /*Cost*/ 2,
        getOperandsMapping(
            {getValueMapping(getVecPartialMappingIdx(MRI.getType(DstReg)),
                             Size),
             getValueMapping(getAccPartialMappingIdx(MRI.getType(DstReg)),
                             Size)}),
        /*NumOperands*/ 2);
    const InstructionMapping &VRegToAccRegMapping = getInstructionMapping(
        /*ID*/ 4, /*Cost*/ 2,
        getOperandsMapping(
            {getValueMapping(getAccPartialMappingIdx(MRI.getType(DstReg)),
                             Size),
             getValueMapping(getVecPartialMappingIdx(MRI.getType(DstReg)),
                             Size)}),
        /*NumOperands*/ 2);

    AltMappings.push_back(&VRegMapping);
    AltMappings.push_back(&AccRegMapping);
    AltMappings.push_back(&AccToVRegMapping);
    AltMappings.push_back(&VRegToAccRegMapping);
    return AltMappings;
  }
  case TargetOpcode::G_TRUNC: {
    Register SrcReg = MI.getOperand(1).getReg();
    LLT SrcTy = MRI.getType(SrcReg);
    if (SrcTy.isVector())
      // TODO : find registerbank using use-def analysis as we do other
      // places.
      return RegisterBankInfo::getInstrAlternativeMappings(MI);
    break;
  }
  default:
    break;
  }
  return AIEBaseRegisterBankInfo::getInstrAlternativeMappings(MI);
}

const RegisterBankInfo::InstructionMapping &
AIE2PSRegisterBankInfo::getInstrMapping(const MachineInstr &MI) const {
  const unsigned Opc = MI.getOpcode();

  const MachineFunction &MF = *MI.getParent()->getParent();
  const MachineRegisterInfo &MRI = MF.getRegInfo();
  const TargetSubtargetInfo &STI = MF.getSubtarget();
  const TargetRegisterInfo &TRI = *STI.getRegisterInfo();

  const unsigned NumOperands = MI.getNumOperands();
  unsigned Cost = 1;

  // Track the size and bank of each register..
  SmallVector<unsigned, 4> OpSize(NumOperands);
  SmallVector<PartialMappingIdx, 4> OpRegBankIdx(NumOperands);

  switch (Opc) {
  case TargetOpcode::G_PHI: {
    // Handle PHI nodes for vector types >= 512 bits
    const Register DstReg = MI.getOperand(0).getReg();
    const LLT DstType = MRI.getType(DstReg);

    // Only handle vector PHIs >= 512 bits
    if (!(DstType.isVector() && DstType.getSizeInBits() >= 512))
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);

    // Check if PHI result prefers accumulator bank
    const auto PreferredRegBank =
        getPreferredRegBankForVectorTy(MRI, TRI, DstReg);
    PartialMappingIdx BankIdx;

    if (PreferredRegBank && *PreferredRegBank == &AIE2PS::AccRegBank) {
      BankIdx = getAccPartialMappingIdx(DstType);
    } else if (PreferredRegBank && *PreferredRegBank == &AIE2PS::FifoRegBank) {
      BankIdx = getFifoPartialMappingIdx(DstType);
    } else {
      BankIdx = getVecPartialMappingIdx(DstType);
    }

    // For PHI nodes, we only map the definition (operand 0)
    // The mapping framework handles PHI as copy-like instructions
    const unsigned DstSize = DstType.getSizeInBits();
    const ValueMapping *ValMapping = getValueMapping(BankIdx, DstSize);

    return getInstructionMapping(DefaultMappingID, Cost,
                                 getOperandsMapping({ValMapping}),
                                 /*NumOperands*/ 1);
  }
  case TargetOpcode::G_BITCAST: {
    // Check if that G_BITCAST feeds acc instructions.
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg = MI.getOperand(1).getReg();
    LLT DstType = MRI.getType(DstReg);
    LLT SrcType = MRI.getType(SrcReg);
    if (SrcType.getSizeInBits() <= 64)
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);
    // Check if we already know the register bank.
    auto *RB = getRegBank(SrcReg, MRI, TRI);
    auto PreferredRegBank = getPreferredRegBankForVectorTy(MRI, TRI, DstReg);
    if ((PreferredRegBank && &AIE2PS::AccRegBank == *PreferredRegBank) ||
        (RB == &AIE2PS::AccRegBank)) {
      OpRegBankIdx[0] = getAccPartialMappingIdx(DstType);
      OpRegBankIdx[1] = getAccPartialMappingIdx(SrcType);
    } else {
      OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
      OpRegBankIdx[1] = getVecPartialMappingIdx(SrcType);
    }

    return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                         OpRegBankIdx);
  }
  case TargetOpcode::G_INTRINSIC:
  case TargetOpcode::G_INTRINSIC_W_SIDE_EFFECTS: {
    for (unsigned Idx = 0; Idx < NumOperands; ++Idx) {
      const auto &MO = MI.getOperand(Idx);
      if (!MO.isReg() || !MO.getReg())
        continue;
      LLT Ty = MRI.getType(MO.getReg());
      if (!Ty.isValid())
        continue;
      if (!(Ty.isVector() && Ty.getSizeInBits() >= 256)) {
        OpRegBankIdx[Idx] = getPartialMappingIdx(MRI.getType(MO.getReg()));
        continue;
      }
      auto PreferredRegBank =
          getRegBankForVectorTy(MRI, TRI, MI, MI.getOperand(Idx).getReg());
      OpRegBankIdx[Idx] =
          AIE2PSRegisterBankInfo::getPartialMappingIdxFromBankAndType(
              PreferredRegBank, Ty);
    }
    return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                         OpRegBankIdx);
  }
  case TargetOpcode::G_UNMERGE_VALUES: {
    assert(MI.getNumOperands() == 3 &&
           "Unsupported number of operands for G_UNMERGE_VALUES\n");
    const Register SrcReg = MI.getOperand(2).getReg();
    const LLT SrcTy = MRI.getType(SrcReg);
    const LLT HalfSrcTy = SrcTy.divide(2);
    const unsigned HalfSrcTySize = HalfSrcTy.getSizeInBits();
    auto *RB = getRegBank(SrcReg, MRI, TRI);

    auto IsUnmergeUsedByAcc = [&](const MachineInstr *UnmergeMI) -> bool {
      return any_of(MI.defs(), [&](const MachineOperand &MO) {
        auto RegBank = getPreferredRegBankForVectorTy(MRI, TRI, MO.getReg());
        return RegBank && *RegBank == &AIE2PS::AccRegBank;
      });
    };

    // Scalars and vectors <= 256-bit are handled by the base implementation
    if (!SrcTy.isVector() || SrcTy.getSizeInBits() <= 256)
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);

    if (SrcTy.getSizeInBits() > 512 &&
        (RB == &AIE2PS::AccRegBank || IsUnmergeUsedByAcc(&MI))) {
      return getInstructionMapping(
          /*ID*/ 1, /*Cost*/ 1,
          getOperandsMapping(
              {getValueMapping(getAccPartialMappingIdx(HalfSrcTy),
                               HalfSrcTySize),
               getValueMapping(getAccPartialMappingIdx(HalfSrcTy),
                               HalfSrcTySize),
               getValueMapping(getAccPartialMappingIdx(SrcTy),
                               SrcTy.getSizeInBits())}),
          /*NumOperands*/ 3);
    }

    return getInstructionMapping(
        /*ID*/ 1, /*Cost*/ 1,
        getOperandsMapping(
            {getValueMapping(getVecPartialMappingIdx(HalfSrcTy), HalfSrcTySize),
             getValueMapping(getVecPartialMappingIdx(HalfSrcTy), HalfSrcTySize),
             getValueMapping(getVecPartialMappingIdx(SrcTy),
                             SrcTy.getSizeInBits())}),
        /*NumOperands*/ 3);
  }
  case TargetOpcode::G_CONCAT_VECTORS: {
    // Check if G_CONCAT_VECTORS feeds acc instructions.
    Register DstReg = MI.getOperand(0).getReg();
    LLT DstType = MRI.getType(DstReg);

    auto PreferredRegBank = getPreferredRegBankForVectorTy(MRI, TRI, DstReg);
    if (DstType.getSizeInBits() > 512 && PreferredRegBank &&
        &AIE2PS::AccRegBank == *PreferredRegBank) {
      OpRegBankIdx[0] = getAccPartialMappingIdx(DstType);
      for (unsigned Idx = 1; Idx < NumOperands; ++Idx) {
        LLT Type = MRI.getType(MI.getOperand(Idx).getReg());
        OpRegBankIdx[Idx] = getAccPartialMappingIdx(Type);
      }
      return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                           OpRegBankIdx);
    } else if (DstType.isVector() && DstType.getSizeInBits() >= 512) {
      OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
      for (unsigned Idx = 1; Idx < NumOperands; ++Idx) {
        LLT Type = MRI.getType(MI.getOperand(Idx).getReg());
        OpRegBankIdx[Idx] = getVecPartialMappingIdx(Type);
      }
      return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                           OpRegBankIdx);
    }
    return AIEBaseRegisterBankInfo::getInstrMapping(MI);
  }
  case TargetOpcode::G_LOAD:
  case AIE2PS::G_AIE_OFFSET_LOAD:
  case AIE2PS::G_AIE_POSTINC_LOAD:
  case AIE2PS::G_AIE_POSTINC_2D_LOAD:
  case AIE2PS::G_AIE_POSTINC_3D_LOAD: {

    // Check if that load feeds acc or fifo instructions.
    Register UseCandidate = MI.getOperand(0).getReg();
    LLT Type = MRI.getType(UseCandidate);

    if (!(Type.isVector() && Type.getSizeInBits() > 128))
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);

    unsigned MappingIdx;
    // Check if we already know the register bank.
    auto *RB = getRegBank(UseCandidate, MRI, TRI);
    if (RB == &AIE2PS::AccRegBank || RB == &AIE2PS::FifoRegBank ||
        RB == &AIE2PS::VRegBank) {
      if (RB == &AIE2PS::FifoRegBank) {
        // G_LOAD cannnot support FifoReg
        RB = &AIE2PS::VRegBank;
      }
      MappingIdx = getPartialMappingIdxFromBankAndType(RB, Type);
    } else {
      auto PreferredRegBank =
          getPreferredRegBankForVectorTy(MRI, TRI, UseCandidate);
      auto RB = &AIE2PS::VRegBank;
      if (PreferredRegBank && PreferredRegBank != &AIE2PS::FifoRegBank) {
        // G_LOAD cannnot support FifoReg
        RB = *PreferredRegBank;
      }
      MappingIdx = getPartialMappingIdxFromBankAndType(RB, Type);
    }

    // First source Idx (pointer reg)
    const unsigned FirstSrcIdx = MI.getNumExplicitDefs();

    // Set all operand mapping indices to PMI_MOD by default.
    // Set all operand sizes to 20 by default.
    OpSize.assign(NumOperands, 20);
    OpRegBankIdx.assign(NumOperands, PMI_MOD);
    // Set up vector operand indices
    OpRegBankIdx[0] =
        static_cast<AIEBaseRegisterBankInfo::PartialMappingIdx>(MappingIdx);
    // Assign PMI_PTR and PMI_MOD based on FirstSrcIdx
    for (unsigned I = 1; I < FirstSrcIdx; ++I) {
      OpRegBankIdx[I] = (I == 1) ? PMI_PTR : PMI_MOD;
    }
    // Assign PMI_PTR at FirstSrcIdx
    OpRegBankIdx[FirstSrcIdx] = PMI_PTR;
    return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                         OpRegBankIdx);
  }
  case TargetOpcode::G_STORE:
  case AIE2PS::G_AIE_OFFSET_STORE:
  case AIE2PS::G_AIE_POSTINC_STORE:
  case AIE2PS::G_AIE_POSTINC_2D_STORE:
  case AIE2PS::G_AIE_POSTINC_3D_STORE: {

    // Select the operand index for VecReg.
    const unsigned VecRegOpIdx = MI.getNumExplicitDefs();
    Register VecReg = MI.getOperand(VecRegOpIdx).getReg();
    auto Ty = MRI.getType(VecReg);
    if (!(Ty.isVector() && Ty.getSizeInBits() > 128))
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);

    auto *DefRegBank = getRegBank(VecReg, MRI, TRI);
    auto RB = &AIE2PS::VRegBank;
    if (DefRegBank && DefRegBank != &AIE2PS::FifoRegBank) {
      // G_STORE cannnot support FifoReg
      RB = DefRegBank;
    }
    const unsigned MappingIdx = getPartialMappingIdxFromBankAndType(RB, Ty);

    // Set all operand mapping indices to PMI_MOD by default.
    // Set all operand sizes to 20 by default.
    OpSize.assign(NumOperands, 20);
    OpRegBankIdx.assign(NumOperands, PMI_MOD);

    // Initialize first few indices based on VRegOpIdx
    for (unsigned I = 0; I < VecRegOpIdx; ++I) {
      OpRegBankIdx[I] = (I == 0) ? PMI_PTR : PMI_MOD;
    }
    OpRegBankIdx[VecRegOpIdx] =
        static_cast<AIEBaseRegisterBankInfo::PartialMappingIdx>(MappingIdx);

    // Assign PMI_PTR to the next operand if within bounds
    assert(((VecRegOpIdx + 1) < NumOperands) && "RegOpIdx + 1 out of bounds");
    OpRegBankIdx[VecRegOpIdx + 1] = PMI_PTR;

    return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                         OpRegBankIdx);
  }
  case TargetOpcode::G_IMPLICIT_DEF: {

    // Check if that IMPLICIT_DEF feeds acc instructions.
    Register DstReg = MI.getOperand(0).getReg();
    auto Type = MRI.getType(DstReg);
    if (!(Type.isVector() && Type.getSizeInBits() >= 256)) {
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);
    }
    // Check if we already know the register bank.
    auto *RB = getRegBank(DstReg, MRI, TRI);
    if (RB == &AIE2PS::AccRegBank)
      return AIEBaseRegisterBankInfo::getInstrMapping(MI);

    auto PreferredRegBank = getPreferredRegBankForVectorTy(MRI, TRI, DstReg);
    OpRegBankIdx[0] =
        AIE2PSRegisterBankInfo::getPartialMappingIdxFromBankAndType(
            PreferredRegBank, Type);
    LLVM_DEBUG(dbgs() << OpRegBankIdx[0] << "\n");
    return AIEBaseRegisterBankInfo::getInstrMappingFinal(MI, Cost, OpSize,
                                                         OpRegBankIdx);
  }
  default:
    // Base class implementation for others
    return AIEBaseRegisterBankInfo::getInstrMapping(MI);
  }
  return AIEBaseRegisterBankInfo::getInstrMapping(MI);
}

void AIE2PSRegisterBankInfo::setAIEGenericInstrMapping(
    const MachineInstr &MI, SmallVector<unsigned, 4> &OpSize,
    SmallVector<PartialMappingIdx, 4> &OpRegBankIdx) const {
  const MachineFunction &MF = *MI.getParent()->getParent();
  const MachineRegisterInfo &MRI = MF.getRegInfo();
  switch (MI.getOpcode()) {
  case AIE2PS::G_AIE_OFFSET_STORE:
  case AIE2PS::G_AIE_OFFSET_LOAD:
  case AIE2PS::G_AIE_OFFSET_ZEXTLOAD:
  case AIE2PS::G_AIE_OFFSET_SEXTLOAD: {
    // Offset is operand #2
    OpRegBankIdx[2] = PMI_MOD;
    // A loaded pointer whose every use forces it onto a GPR is mapped to the
    // GPR bank directly, avoiding a ptr->gpr bridging copy.
    if (MI.getOpcode() == AIE2PS::G_AIE_OFFSET_LOAD &&
        pointerLoadDefShouldBeGPR(MI, MRI))
      OpRegBankIdx[0] = PMI_GPR;
    break;
  }
  case AIE2PS::G_AIE_POSTINC_STORE:
  case AIE2PS::G_AIE_POSTINC_LOAD:
  case AIE2PS::G_AIE_POSTINC_ZEXTLOAD:
  case AIE2PS::G_AIE_POSTINC_SEXTLOAD: {
    // Offset is operand #3
    OpRegBankIdx[3] = PMI_MOD;
    // The loaded value is def #0 (def #1 is the incremented pointer, which
    // stays on the pointer bank for addressing). If the loaded pointer value's
    // every use forces it onto a GPR, map def #0 to the GPR bank directly to
    // avoid a ptr->gpr bridging copy.
    if (MI.getOpcode() == AIE2PS::G_AIE_POSTINC_LOAD &&
        pointerLoadDefShouldBeGPR(MI, MRI))
      OpRegBankIdx[0] = PMI_GPR;
    break;
  }
  case AIE2PS::G_AIE_UNPAD_VECTOR:
  case AIE2PS::G_AIE_PAD_VECTOR_UNDEF: {
    // Pad/Unpad typically pads/discards 128-/256-bit, which is only supported
    // on the vector register bank
    Register SrcReg0 = MI.getOperand(1).getReg();
    Register DstReg = MI.getOperand(0).getReg();
    LLT SrcType0 = MRI.getType(SrcReg0);
    LLT DstType = MRI.getType(DstReg);
    OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
    OpRegBankIdx[1] = getVecPartialMappingIdx(SrcType0);
    break;
  }
  case AIE2PS::G_AIE_ADD_VECTOR_ELT_HI: {
    Register DstReg = MI.getOperand(0).getReg();
    Register SrcReg0 = MI.getOperand(1).getReg();
    LLT DstType = MRI.getType(DstReg);
    LLT SrcType0 = MRI.getType(SrcReg0);
    assert(DstType.getSizeInBits() == 512 &&
           "Unsupported vector size for G_AIE_ADD_VECTOR_ELT_HI!");
    OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
    OpRegBankIdx[1] = getVecPartialMappingIdx(SrcType0);
    break;
  }
  case AIE2PS::G_AIE_BROADCAST_VECTOR: {
    Register DstReg = MI.getOperand(0).getReg();
    LLT DstType = MRI.getType(DstReg);
    unsigned Size = DstType.getSizeInBits();
    // 512-bit size is supported using VBCST and 2048-bit using VCLR
    assert((Size == 512 || Size == 2048) &&
           "Unsupported vector size for G_AIE_BROADCAST_VECTOR!");
    if (Size == 2048)
      OpRegBankIdx[0] = getAccPartialMappingIdx(DstType);
    else
      OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
    break;
  }

  case AIE2PS::G_AIE_INSERT_VECTOR_ELT: {
    LLT DstType = MRI.getType(MI.getOperand(0).getReg());
    LLT SrcType = MRI.getType(MI.getOperand(1).getReg());
    assert(DstType == SrcType);
    OpRegBankIdx[0] = getVecPartialMappingIdx(DstType);
    OpRegBankIdx[1] = getVecPartialMappingIdx(SrcType);
    break;
  }
  }
}

const RegisterBank &
AIE2PSRegisterBankInfo::getRegBankFromRegClass(const TargetRegisterClass &RC,
                                               LLT Ty) const {
  const auto &GPRs = getRegBank(AIE2PS::GPRRegBankID);
  const auto &PTRs = getRegBank(AIE2PS::PTRRegBankID);
  const auto &MODs = getRegBank(AIE2PS::MODRegBankID);
  const auto &VECs = getRegBank(AIE2PS::VRegBankID);
  const auto &ACCs = getRegBank(AIE2PS::AccRegBankID);
  const auto &FIFOs = getRegBank(AIE2PS::FifoRegBankID);
  if (GPRs.covers(RC)) {
    return GPRs;
  }
  if (PTRs.covers(RC)) {
    return PTRs;
  }
  if (MODs.covers(RC)) {
    return MODs;
  }
  if (VECs.covers(RC)) {
    return VECs;
  }
  if (ACCs.covers(RC)) {
    return ACCs;
  }
  if (FIFOs.covers(RC)) {
    return FIFOs;
  }
  // All register classes are not covered by the register banks(see
  // AIE2PSRegisterBanks.td), as it can cause problems in the ISel. For example,
  // if we include eSRegClass to GPRRegBank, then during ISel, target
  // instruction which has an operand constrained to eSRegClass will be
  // constraining register to eSRegClass and leads to target independent
  // instructions already register constrained even before instruction
  // selection. If not, a copy is inserted.
  // However, we need a bank for these register classes which we
  // handle here.
  switch (RC.getID()) {
  case AIE2PS::eSRegClassID:
  case AIE2PS::mS2RegClassID:
  case AIE2PS::mS3RegClassID:
  case AIE2PS::mSsRegClassID:
    return GPRs;
  default:
    break;
  }
  dbgs() << "ID: " << RC.getID() << "\n";
  llvm_unreachable("Register class not supported");
}

void AIE2PSRegisterBankInfo::applyMappingImpl(
    MachineIRBuilder &Builder, const OperandsMapper &OpdMapper) const {
  switch (OpdMapper.getMI().getOpcode()) {
  case TargetOpcode::G_BITCAST:
    // Those ID must match getInstrAlternativeMappings.
    assert((OpdMapper.getInstrMapping().getID() >= 1 &&
            OpdMapper.getInstrMapping().getID() <= 4) &&
           "Don't know how to handle that ID");
    return applyDefaultMapping(OpdMapper);
  default:
    break;
  }
  AIEBaseRegisterBankInfo::applyMappingImpl(Builder, OpdMapper);
}
